// Use the native console in the browser extension context
// (remove: const console = require('./console');)

// Helper: get the runtime API (chrome or browser, for compatibility)
const runtime = (typeof browser !== 'undefined') ? browser.runtime : chrome.runtime;

// Inject scripts into the page
window.addEventListener('load', () => {
  const scriptsToInject = ['nflxmultisubs.min.js'];
  scriptsToInject.forEach(scriptName => {
    const scriptElem = document.createElement('script');
    scriptElem.type = 'text/javascript';
    scriptElem.src = runtime.getURL(scriptName);
    scriptElem.id = runtime.id;
    document.head.appendChild(scriptElem);
    console.log(`Injected: ${scriptName}`);
  });
});

// Relay messaging for settings and playback actions
let gMsgPort = null;

window.addEventListener('message', evt => {
  if (!evt.data || evt.data.namespace !== 'nflxmultisubs') return;

  switch (evt.data.action) {
    case 'connect':
      if (!gMsgPort) {
        gMsgPort = runtime.connect(runtime.id);
        gMsgPort.onMessage.addListener(msg => {
          if (msg.settings) {
            window.postMessage({
              namespace: 'nflxmultisubs',
              action: 'apply-settings',
              settings: msg.settings,
            }, '*');
          }
        });
      }
      break;

    case 'disconnect':
      if (gMsgPort) {
        gMsgPort.disconnect();
        gMsgPort = null;
      }
      break;

    case 'update-settings':
      if (gMsgPort && evt.data.settings) {
        gMsgPort.postMessage({ settings: evt.data.settings });
      }
      break;

    case 'startPlayback':
      if (gMsgPort) {
        gMsgPort.postMessage({ startPlayback: 1 });
      }
      break;

    case 'stopPlayback':
      if (gMsgPort) {
        gMsgPort.postMessage({ stopPlayback: 1 });
      }
      break;

    // Optionally, add a default case for unknown actions
  }
}, false);
